### code
```python
import json
from datetime import datetime

def task_func(json_data):
    try:
        data = json.loads(json_data) if isinstance(json_data, str) else json_data
        utc_datetime = data.get("utc_datetime")
        if not utc_datetime:
            return False

        if isinstance(utc_datetime, datetime):
            dt = utc_datetime
        else:
            utc_datetime = str(utc_datetime).strip()
            if utc_datetime.endswith("Z"):
                utc_datetime = utc_datetime[:-1] + "+00:00"

            try:
                dt = datetime.fromisoformat(utc_datetime)
            except ValueError:
                formats = [
                    "%Y-%m-%d %H:%M:%S",
                    "%Y-%m-%dT%H:%M:%S",
                    "%Y-%m-%d",
                    "%m/%d/%Y %H:%M:%S",
                    "%m/%d/%Y"
                ]
                dt = None
                for fmt in formats:
                    try:
                        dt = datetime.strptime(utc_datetime, fmt)
                        break
                    except ValueError:
                        pass
                if dt is None:
                    return False

        return dt.weekday() in (5, 6)
    except Exception:
        return False
