import pandas as pd
import os
import json
from collections import Counter

def task_func(json_dir_path, word_count):
    def extract_text(obj):
        texts = []
        if isinstance(obj, dict):
            for key, value in obj.items():
                if key == "text":
                    texts.append(str(value))
                elif isinstance(value, (dict, list)):
                    texts.extend(extract_text(value))
        elif isinstance(obj, list):
            for item in obj:
                texts.extend(extract_text(item))
        elif isinstance(obj, str):
            texts.append(obj)
        return texts

    counter = Counter()

    for filename in sorted(os.listdir(json_dir_path)):
        if filename.endswith(".json"):
            file_path = os.path.join(json_dir_path, filename)
            with open(file_path, "r") as f:
                try:
                    data = json.load(f)
                except json.JSONDecodeError:
                    continue

            for text in extract_text(data):
                cleaned = "".join(ch.lower() if ch.isalnum() or ch.isspace() else " " for ch in text)
                counter.update(cleaned.split())

    return counter.most_common(word_count)

