from glob import glob
def task_func(directory, string):
    def contains_string(data):
        if isinstance(data, dict):
            for key, value in data.items():
                if isinstance(key, str) and string in key:
                    return True
                if contains_string(value):
                    return True
            return False
        if isinstance(data, list):
            return any(contains_string(item) for item in data)
        if isinstance(data, str):
            return string in data
        return False

    matching_files = []

    for file_path in glob(f"{directory}/**/*.json", recursive=True):
        try:
            with open(file_path, "r") as f:
                data = json.load(f)
            if contains_string(data):
                matching_files.append(file_path)
        except Exception:
            continue

    return matching_files

