import json
import re
import pandas as pd

def task_func(json_str):
    if not json_str:
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, TypeError):
        return pd.DataFrame()

    if not isinstance(data, dict) or not data:
        return pd.DataFrame()

    def normalize_value(value):
        if isinstance(value, bool):
            return value

        if isinstance(value, (int, float)):
            return float(value) * 2

        if isinstance(value, list):
            return [normalize_value(item) for item in value]

        if isinstance(value, str):
            stripped = value.strip()
            if re.fullmatch(r"[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?", stripped):
                return float(stripped) * 2

            numbers = re.findall(r"[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?", value)
            if len(numbers) == 1:
                return float(numbers[0]) * 2
            if len(numbers) > 1:
                return [float(num) * 2 for num in numbers]

            return value

        return value

    normalized = {key: normalize_value(value) for key, value in data.items()}

    try:
        if any(isinstance(value, list) for value in normalized.values()):
            return pd.DataFrame(normalized)
        return pd.DataFrame([normalized])
    except ValueError:
        try:
            return pd.DataFrame([normalized])
        except Exception:
            return pd.DataFrame()

