import pandas as pd
def task_func(json_str):
    if not json_str:
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, TypeError):
        return pd.DataFrame()

    if not isinstance(data, dict) or not data:
        return pd.DataFrame()

    number_pattern = r'[-+]?(?:\d*\.\d+|\d+)(?:[eE][-+]?\d+)?'

    def normalize_value(value):
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return float(value) * 2
        if isinstance(value, list):
            return [normalize_value(item) for item in value]
        if isinstance(value, str):
            numbers = re.findall(number_pattern, value)
            if not numbers:
                return value
            doubled = [float(num) * 2 for num in numbers]
            return doubled[0] if len(doubled) == 1 else doubled
        return value

    normalized = {key: normalize_value(value) for key, value in data.items()}

    list_lengths = [len(value) for value in normalized.values() if isinstance(value, list)]

    if list_lengths:
        max_len = max(list_lengths)
        if max_len == 0:
            return pd.DataFrame(columns=normalized.keys())

        frame_data = {}
        for key, value in normalized.items():
            if isinstance(value, list):
                frame_data[key] = value + [None] * (max_len - len(value))
            else:
                frame_data[key] = [value] * max_len
        return pd.DataFrame(frame_data)

    return pd.DataFrame([normalized])

import json
import pandas as pd
import numpy as np
from collections import defaultdict
def task_func(input_file="data.json"):
    with open(input_file, "r") as f:
        data = json.load(f)

    values = defaultdict(list)
    all_keys = set()

    for item in data:
        if isinstance(item, dict):
            for key, value in item.items():
                all_keys.add(key)
                if isinstance(value, (int, float, np.number)) and not isinstance(value, bool):
                    if not pd.isna(value):
                        values[key].append(value)

    result = {}
    for key in all_keys:
        numeric_values = values[key]
        result[key] = {
            "mean": np.mean(numeric_values) if numeric_values else np.nan,
            "median": np.median(numeric_values) if numeric_values else np.nan
        }

    df = pd.DataFrame.from_dict(result, orient="index", columns=["mean", "median"])
    df = df.sort_index()
    return df

