import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except Exception as e:
        raise ValueError("JSON data is malformed") from e

    if not data:
        raise ValueError("JSON data is empty")

    records = []

    if isinstance(data, dict):
        if "Country" in data and "Population" in data:
            records = [data]
        elif "country" in data and "population" in data:
            records = [{"Country": data["country"], "Population": data["population"]}]
        else:
            records = [{"Country": country, "Population": population} for country, population in data.items()]
    elif isinstance(data, list):
        if len(data) == 0:
            raise ValueError("JSON data is empty")
        for item in data:
            if not isinstance(item, dict):
                raise ValueError("JSON data is malformed")
            if "Country" in item and "Population" in item:
                records.append({"Country": item["Country"], "Population": item["Population"]})
            elif "country" in item and "population" in item:
                records.append({"Country": item["country"], "Population": item["population"]})
            else:
                raise ValueError("JSON data is malformed")
    else:
        raise ValueError("JSON data is malformed")

    cleaned_records = []

    for record in records:
        country = record.get("Country")
        population = record.get("Population")

        if not isinstance(country, str):
            raise ValueError("Country names must be strings")

        if isinstance(population, bool) or not isinstance(population, (int, float)):
            raise ValueError("Populations must be numeric")

        if not math.isfinite(population) or population < 0:
            raise ValueError("Populations must be non-negative finite numbers")

        cleaned_records.append({
            "Country": country,
            "Population": int(math.floor(population))
        })

    df = pd.DataFrame(cleaned_records, columns=["Country", "Population"])

    file_path = os.path.join(output_dir, file_name)

    try:
        df.to_csv(file_path, index=False)
    except Exception as e:
        raise IOError("File cannot be written to the specified directory") from e

    return file_path, df

