import pandas as pd
import json
import os
import math

def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        if isinstance(json_data, (str, bytes, bytearray)):
            data = json.loads(json_data)
        else:
            data = json_data
    except (json.JSONDecodeError, TypeError):
        raise ValueError("JSON data is malformed")

    if not data:
        raise ValueError("JSON data is empty")

    records = []

    def validate_record(country, population):
        if not isinstance(country, str):
            raise ValueError("Country names must be strings")
        if isinstance(population, bool) or not isinstance(population, (int, float)):
            raise ValueError("Populations must be numeric")
        if not math.isfinite(population) or population < 0:
            raise ValueError("Populations must be non-negative")
        return {"Country": country, "Population": math.floor(population)}

    if isinstance(data, list):
        if len(data) == 0:
            raise ValueError("JSON data is empty")
        for item in data:
            if not isinstance(item, dict):
                raise ValueError("JSON records must be dictionaries")
            if "Country" in item and "Population" in item:
                country = item["Country"]
                population = item["Population"]
            elif "country" in item and "population" in item:
                country = item["country"]
                population = item["population"]
            else:
                raise ValueError("JSON records must contain country and population data")
            records.append(validate_record(country, population))
    elif isinstance(data, dict):
        if "Country" in data and "Population" in data:
            records.append(validate_record(data["Country"], data["Population"]))
        elif "country" in data and "population" in data:
            records.append(validate_record(data["country"], data["population"]))
        else:
            for country, population in data.items():
                records.append(validate_record(country, population))
    else:
        raise ValueError("JSON data is malformed")

    if not records:
        raise ValueError("JSON data is empty")

    df = pd.DataFrame(records, columns=["Country", "Population"])
    file_path = os.path.join(output_dir, file_name)

    try:
        os.makedirs(output_dir, exist_ok=True)
        df.to_csv(file_path, index=False)
    except OSError as e:
        raise IOError("File cannot be written to the specified directory") from e

    return file_path, df

