    except (json.JSONDecodeError, TypeError):
        raise ValueError("JSON data is empty or corrupted")

    def traverse(obj, path):
        if not path:
            return obj

        key = path[0]
        remaining = path[1:]

        if isinstance(obj, dict):
            if key not in obj:
                raise KeyError(key)
            return traverse(obj[key], remaining)

        if isinstance(obj, list):
            if isinstance(key, int):
                try:
                    return traverse(obj[key], remaining)
                except IndexError:
                    raise KeyError(key)
            return [traverse(item, path) for item in obj]

        raise KeyError(key)

    selected_data = traverse(data, key_path)

    values = []

    def extract_numbers(obj):
        if isinstance(obj, bool):
            return

        if isinstance(obj, (int, float, np.integer, np.floating)):
            value = float(obj)
            if np.isfinite(value):
                values.append(value)
            return

        if isinstance(obj, str):
            text = obj.strip()
            if not text:
                return

            try:
                parsed = json.loads(text)
                extract_numbers(parsed)
                return
            except json.JSONDecodeError:
                pass

            numeric_value = pd.to_numeric(text, errors="coerce")
            if not pd.isna(numeric_value) and np.isfinite(float(numeric_value)):
