import matplotlib.pyplot as plt
def task_func(json_data: str, data_key: str):
    data = json.loads(json_data)

    def get_value(obj, path):
        if isinstance(obj, dict) and path in obj:
            return obj[path]

        current = obj
        for part in path.split("."):
            if isinstance(current, dict):
                if part not in current:
                    raise KeyError(path)
                current = current[part]
            elif isinstance(current, list):
                try:
                    index = int(part)
                    current = current[index]
                except (ValueError, IndexError):
                    raise KeyError(path)
            else:
                raise KeyError(path)
        return current

    extracted = get_value(data, data_key)

    if isinstance(extracted, dict):
        values = list(extracted.values())
    elif isinstance(extracted, (list, tuple)):
        values = extracted
    else:
        values = [extracted]

    original = pd.to_numeric(pd.Series(values), errors="coerce").dropna().astype("float64").reset_index(drop=True)

    if original.empty:
        return original, None, None

    scaler = MinMaxScaler()
    normalized_values = scaler.fit_transform(original.to_numpy().reshape(-1, 1)).flatten()
    normalized = pd.Series(normalized_values, dtype="float64")

    _, ax = plt.subplots()
    ax.plot(original.index, original.values, label="Original Data")
    ax.plot(normalized.index, normalized.values, label="Normalized Data")
    ax.set_title("Comparison of Original and Normalized Data")
    ax.set_xlabel("Index")
    ax.set_ylabel("Value")
    ax.legend()

    return original, normalized, ax

